/**
 * Renderiza un template con datos dinámicos.
 * @param {string} template - La cadena del template.
 * @param {Object} data - El objeto de contexto con los datos.
 * @param {Object} options - Opciones adicionales (customHelpers, strictMode, preserveWhitespace).
 * @returns {string} - El HTML o texto renderizado.
 */
function renderTemplate(template, data = {}, options = {}) {
  const {
    customHelpers = {},
    strictMode = false,
    preserveWhitespace = false,
  } = options;

  // --- 1. Definición de Helpers y Utilidades ---
  const defaultHelpers = {
    // Helper de debugging
    debug: (...args) => {
      console.log("DEBUG:", args);
      return args[0];
    },

    // Helpers de formato
    uppercase: (str) => String(str).toUpperCase(),
    lowercase: (str) => String(str).toLowerCase(),
    capitalize: (str) => {
      const s = String(str);
      return s.charAt(0).toUpperCase() + s.slice(1);
    },
    date: (date, format) => {
      const d = new Date(date);
      if (isNaN(d.getTime())) return String(date);
      if (format === "short") return d.toLocaleDateString("es-ES");
      if (format === "long")
        return d.toLocaleDateString("es-ES", {
          weekday: "long",
          year: "numeric",
          month: "long",
          day: "numeric",
        });
      return d.toLocaleDateString("es-ES");
    },

    // Helpers Numéricos
    toFixed: (num, digits) => {
      const n = Number(num);
      return isNaN(n) ? num : n.toFixed(digits || 2);
    },
    currency: (num, currencyCode = "EUR", locale = "es-ES") => {
      const n = Number(num);
      if (isNaN(n)) return num;
      return new Intl.NumberFormat(locale, {
        style: "currency",
        currency: currencyCode,
      }).format(n);
    },
    number: (num, decimals = 2, locale = "es-ES") => {
      const n = Number(num);
      if (isNaN(n)) return num;
      return new Intl.NumberFormat(locale, {
        minimumFractionDigits: decimals,
        maximumFractionDigits: decimals,
      }).format(n);
    },
    percent: (num, decimals = 0, locale = "es-ES") => {
      const n = Number(num);
      if (isNaN(n)) return num;
      return new Intl.NumberFormat(locale, {
        style: "percent",
        minimumFractionDigits: decimals,
        maximumFractionDigits: decimals,
      }).format(n / 100);
    },
    round: (num) => Math.round(Number(num)),
    ceil: (num) => Math.ceil(Number(num)),
    floor: (num) => Math.floor(Number(num)),
    padStart: (val, length, char) => String(val).padStart(length, char || "0"),

    // Helpers de comparación
    eq: (a, b) => {
      // Normalizar valores para comparación
      const normA =
        typeof a === "string"
          ? a.replace(/&quot;|&#34;|&#034;/g, '"').replace(/&#39;|&#039;/g, "'")
          : a;
      const normB =
        typeof b === "string"
          ? b.replace(/&quot;|&#34;|&#034;/g, '"').replace(/&#39;|&#039;/g, "'")
          : b;
      return normA === normB;
    },
    ne: (a, b) => {
      // Normalizar valores para comparación
      const normA =
        typeof a === "string"
          ? a.replace(/&quot;|&#34;|&#034;/g, '"').replace(/&#39;|&#039;/g, "'")
          : a;
      const normB =
        typeof b === "string"
          ? b.replace(/&quot;|&#34;|&#034;/g, '"').replace(/&#39;|&#039;/g, "'")
          : b;
      return normA !== normB;
    },
    gt: (a, b) => Number(a) > Number(b),
    gte: (a, b) => Number(a) >= Number(b),
    lt: (a, b) => Number(a) < Number(b),
    lte: (a, b) => Number(a) <= Number(b),

    // Helpers lógicos
    and: (...args) => args.every(Boolean),
    or: (...args) => args.some(Boolean),
    not: (a) => !a,

    // Helpers de utilidad
    length: (arr) => (Array.isArray(arr) ? arr.length : 0),
    default: (value, defaultValue) => value ?? defaultValue,
    json: (obj) => JSON.stringify(obj, null, 2),
    trim: (str) => String(str).trim(),

    // Helpers matemáticos
    add: (a, b) => Number(a) + Number(b),
    subtract: (a, b) => Number(a) - Number(b),
    multiply: (a, b) => Number(a) * Number(b),
    divide: (a, b) => Number(a) / Number(b),
    mod: (a, b) => Number(a) % Number(b),
  };

  const helpers = { ...defaultHelpers, ...customHelpers };

  const escapeMap = {
    "&": "&amp;",
    "<": "&lt;",
    ">": "&gt;",
    '"': "&quot;",
    "'": "&#039;",
  };

  // --- 2. Funciones Internas de Procesamiento ---
  const escapeHtml = (text) => {
    return String(text).replace(/[&<>"']/g, (m) => escapeMap[m]);
  };

  const getValue = (path, context) => {
    if (path === "this" || path === ".") {
      return context && context._this_ !== undefined ? context._this_ : context;
    }

    if (context == null) return undefined;

    let lookupPath = path;
    if (lookupPath.startsWith("this.")) {
      lookupPath = lookupPath.slice(5);
    }

    // Manejo especial para variables especiales de loop (@key, @index, etc.)
    if (lookupPath.startsWith("@")) {
      return context[lookupPath];
    }

    const keys = lookupPath.split(".");
    let current = context;

    for (const key of keys) {
      if (current == null) return undefined;
      // Soporte para índices de array
      if (/^\d+$/.test(key)) {
        current = current[parseInt(key, 10)];
      } else {
        if (current[key] === undefined && current._this_ !== undefined) {
          current = current._this_;
        }
        current = current[key];
      }
    }
    return current;
  };

  const parseArguments = (argsStr, context) => {
    const args = [];
    // Normalizar las comillas HTML escapadas antes de parsear
    const normalizedStr = argsStr
      .replace(/&quot;/g, '"')
      .replace(/&#39;/g, "'")
      .replace(/&#034;/g, '"')
      .replace(/&#039;/g, "'");

    const argRegex =
      /"([^"]*)"|'([^']*)'|true|false|null|undefined|(-?\d+\.?\d*)|([a-zA-Z_@][\w.@]*)/g;
    let match;

    while ((match = argRegex.exec(normalizedStr)) !== null) {
      if (match[1] !== undefined)
        args.push(match[1]); // Comillas dobles
      else if (match[2] !== undefined)
        args.push(match[2]); // Comillas simples
      else if (match[0] === "true") args.push(true);
      else if (match[0] === "false") args.push(false);
      else if (match[0] === "null") args.push(null);
      else if (match[0] === "undefined") args.push(undefined);
      else if (match[3] !== undefined) args.push(parseFloat(match[3]));
      else if (match[4] !== undefined) args.push(getValue(match[4], context));
    }
    return args;
  };

  const evaluateHelper = (expression, context) => {
    // Normalizar comillas HTML escapadas
    const normalizedExpr = expression
      .replace(/&quot;/g, '"')
      .replace(/&#39;/g, "'")
      .replace(/&#034;/g, '"')
      .replace(/&#039;/g, "'");

    const helperMatch = normalizedExpr.match(/^\((\w+)\s*(.*?)\)$/);

    if (helperMatch) {
      const [, helperName, argsStr] = helperMatch;
      const helper = helpers[helperName];

      if (!helper) {
        if (strictMode) throw new Error(`Helper "${helperName}" no encontrado`);
        console.warn(`Helper "${helperName}" no encontrado`);
        return false;
      }

      const args = parseArguments(argsStr, context);
      const result = helper(...args);

      return result;
    }

    return getValue(normalizedExpr, context);
  };

  const isTruthy = (value) => {
    if (value == null) return false;
    if (typeof value === "boolean") return value;
    if (typeof value === "number") return value !== 0;
    if (typeof value === "string") return value.length > 0;
    if (Array.isArray(value)) return value.length > 0;
    if (typeof value === "object") return Object.keys(value).length > 0;
    return Boolean(value);
  };

  // --- 3. Lógica Principal de Parseo ---
  const processContent = (content, context) => {
    let result = content;

    // 3.1 Condicionales
    result = result.replace(
      /\{\{#if\s+(.+?)\}\}([\s\S]*?)\{\{\/if\}\}/g,
      (match, firstCondition, body) => {
        const sections = [];
        let remaining = body;
        const elseifRegex = /\{\{elseif\s+(.+?)\}\}/g;
        const elseRegex = /\{\{else\}\}/;

        const markers = [];
        let elseifMatch;
        while ((elseifMatch = elseifRegex.exec(remaining)) !== null) {
          markers.push({
            type: "elseif",
            index: elseifMatch.index,
            condition: elseifMatch[1].trim(),
          });
        }

        const elseMatch = elseRegex.exec(remaining);
        if (elseMatch) {
          markers.push({ type: "else", index: elseMatch.index });
        }

        markers.sort((a, b) => a.index - b.index);

        sections.push({
          condition: firstCondition.trim(),
          content:
            markers.length > 0
              ? remaining.substring(0, markers[0].index)
              : remaining,
        });

        for (let i = 0; i < markers.length; i++) {
          const marker = markers[i];
          const nextMarker = markers[i + 1];
          const startIdx = remaining.indexOf("}}", marker.index) + 2;
          const endIdx = nextMarker ? nextMarker.index : remaining.length;

          sections.push({
            condition: marker.condition ?? null,
            content: remaining.substring(startIdx, endIdx),
          });
        }

        for (const section of sections) {
          if (section.condition === null) {
            return processContent(section.content, context);
          }
          const value = evaluateHelper(section.condition, context);
          if (isTruthy(value)) {
            return processContent(section.content, context);
          }
        }
        return "";
      },
    );

    // 3.2 Unless
    result = result.replace(
      /\{\{#unless\s+(.+?)\}\}([\s\S]*?)\{\{\/unless\}\}/g,
      (match, condition, innerContent) => {
        const value = evaluateHelper(condition.trim(), context);
        return !isTruthy(value) ? processContent(innerContent, context) : "";
      },
    );

    // 3.3 Helpers standalone (operaciones matemáticas, etc.)
    result = result.replace(
      /\{\{\((\w+)\s+([^}]+)\)\}\}/g,
      (match, helperName, helperArgs) => {
        const helper = helpers[helperName];

        if (!helper) {
          if (strictMode)
            throw new Error(`Helper "${helperName}" no encontrado`);
          console.warn(`Helper "${helperName}" no encontrado`);
          return "";
        }

        const args = parseArguments(helperArgs, context);
        const res = helper(...args);
        return res !== undefined ? escapeHtml(res) : "";
      },
    );

    // 3.4 Variables con helpers
    result = result.replace(
      /\{\{([\w.@]+|this\.[\w.]+)\|(\w+)(?:\s+([^}]+))?\}\}/g,
      (match, path, helperName, helperArgs) => {
        const value = getValue(path, context);
        const helper = helpers[helperName];

        if (!helper) {
          if (strictMode)
            throw new Error(`Helper "${helperName}" no encontrado`);
          console.warn(`Helper "${helperName}" no encontrado`);
          return value !== undefined ? escapeHtml(value) : "";
        }

        const args = helperArgs
          ? [value, ...parseArguments(helperArgs, context)]
          : [value];

        const res = helper(...args);
        return res !== undefined ? escapeHtml(res) : "";
      },
    );

    // 3.5 Variables sin escapar {{{ }}}
    result = result.replace(
      /\{\{\{([\w.@]+|this\.[\w.]+)\}\}\}/g,
      (match, path) => {
        const value = getValue(path, context);
        return value !== undefined ? String(value) : "";
      },
    );

    // 3.6 Variables escapadas {{ }}
    result = result.replace(
      /\{\{(?!#|\/|elseif|else(?!\w)|\()([\w.@]+|this\.[\w.]+)\}\}/g,
      (match, path) => {
        const value = getValue(path, context);
        return value !== undefined ? escapeHtml(value) : "";
      },
    );

    return result;
  };

  const processLoops = (tmpl, dataCtx) => {
    return tmpl.replace(
      /\{\{#each ([\w.]+)(?:\s+as\s+\|(\w+)(?:\s*,\s*(\w+))?\|)?\}\}([\s\S]*?)\{\{\/each\}\}/g,
      (match, key, itemAlias, indexAlias, content) => {
        const collection = getValue(key, dataCtx);

        let items = [];

        if (Array.isArray(collection)) {
          if (collection.length === 0) return "";
          items = collection.map((item, index) => ({
            _this_: item,
            "@index": index,
            "@first": index === 0,
            "@last": index === collection.length - 1,
            "@odd": index % 2 === 1,
            "@even": index % 2 === 0,
            "@length": collection.length,
          }));
        } else if (typeof collection === "object" && collection !== null) {
          const keys = Object.keys(collection);
          if (keys.length === 0) return "";
          items = keys.map((key, index) => ({
            _this_: collection[key],
            "@key": key,
            "@index": index,
            "@first": index === 0,
            "@last": index === keys.length - 1,
            "@odd": index % 2 === 1,
            "@even": index % 2 === 0,
            "@length": keys.length,
          }));
        } else {
          return "";
        }

        return items
          .map((loopContext) => {
            const isObject =
              typeof loopContext._this_ === "object" &&
              loopContext._this_ !== null;

            if (isObject) {
              Object.assign(loopContext, loopContext._this_);
            }

            return processContent(content, loopContext);
          })
          .join("");
      },
    );
  };

  const cleanWhitespace = (tmpl) => {
    return tmpl
      .replace(/\s*(\{\{#(?:if|unless|each)[^}]*\}\})\s*/g, "$1")
      .replace(/\s*(\{\{\/(?:if|unless|each)\}\})\s*/g, "$1")
      .replace(/\s*(\{\{(?:else|elseif)[^}]*\}\})\s*/g, "$1");
  };

  // --- 4. Ejecución ---
  let processedTemplate = preserveWhitespace
    ? template
    : cleanWhitespace(template);
  processedTemplate = processLoops(processedTemplate, data);
  return processContent(processedTemplate, data);
}

const html = renderTemplate($input.item.json.body_html, $input.item.json.details_json);
const subject = renderTemplate($input.item.json.subject, $input.item.json.details_json);

return {
  html: html,
  subject: subject,
  details_json: $input.item.json.details_json,
  notification_slug: $input.item.json.notification_category_slug
};

parameters.query:
SELECT *
FROM public.alert_system_config
WHERE config_key ILIKE 'scheduler' || '%' ;

parameters.jsCode:
const items = $input.all();
const originalStructure = {};

items.forEach(item => {
  const { config_key, config_value, config_type } = item.json;

  // Separamos "scheduler.enabled" en ["scheduler", "enabled"]
  const [category, key] = config_key.split('.');

  if (!originalStructure[category]) {
    originalStructure[category] = {};
  }

  // Convertimos el valor de texto a su tipo real según config_type
  let parsedValue = config_value;
  if (config_type === 'BOOLEAN') {
    parsedValue = config_value === 'true';
  } else if (config_type === 'NUMBER') {
    parsedValue = Number(config_value);
  }

  originalStructure[category][key] = parsedValue;
});

return { json: originalStructure };

parameters.query:
SELECT MAX(run_date) as last_run 
FROM public.alert_schedule_runs 
WHERE status = 'COMPLETED';

parameters.jsCode:
const today = new Date();
today.setHours(0, 0, 0, 0);

const lastRunData = $input.first().json.last_run;
let startDate;

if (!lastRunData) {
  startDate = new Date(today);
} else {
  startDate = new Date(lastRunData);
  startDate.setDate(startDate.getDate() + 1);
}

const datesToProcess = [];
let currentCursor = new Date(startDate);

while (currentCursor <= today) {
  datesToProcess.push({
    target_date: currentCursor.toISOString().split('T')[0]
  });
  currentCursor.setDate(currentCursor.getDate() + 1);
}

return { datesToProcess };

